*/
```

Step 4: Add the following code to the `text-splitter.php` file to create the plugin settings page:

```php
function ts_admin_menu() {
    add_menu_page( 'Text Splitter', 'Text Splitter', 'manage_options', 'text-splitter', 'ts_admin_page', 'dashicons-edit', 60 );
}
add_action( 'admin_menu', 'ts_admin_menu' );

function ts_admin_page() {
    if ( ! current_user_can( 'manage_options' ) ) {
        wp_die( __( 'You do not have sufficient permissions to access this page.' ) );
    }
    ?>
    <div class="wrap">
        <h1>Text Splitter</h1>
        <form method="post" action="options.php">
            <?php
            settings_fields( 'ts_settings' );
            do_settings_sections( 'text-splitter' );
            submit_button();
            ?>
        </form>
    </div>
    <?php
}

function ts_settings_init() {
    register_setting( 'ts_settings', 'ts_word_count' );
    add_settings_section( 'ts_section_1', 'Settings', 'ts_section_1_callback', 'text-splitter' );
    add_settings_field( 'ts_word_count_field', 'Word Count', 'ts_word_count_field_callback', 'text-splitter', 'ts_section_1' );
}
add_action( 'admin_init', 'ts_settings_init' );

function ts_section_1_callback() {
