            bool first = true;
            for (const auto& [key, val] : value) {
                if (!first) {
                    std::cout << ", ";
                }
                first = false;
                std::cout << '"' << key << "\": ";
                printPyStyleVar(val);
            }
            std::cout << '}';
        }
    }, var);
}

