class PythonVariable {
public:
    enum Type {
        INTEGER,
        STRING,
        ARRAY,
        MAP
    };

    PythonVariable(int value) : type(INTEGER), integerValue(value) {}
    PythonVariable(const std::string& value) : type(STRING), stringValue(value) {}
    PythonVariable(const std::vector<PythonVariable>& value) : type(ARRAY), arrayValue(value) {}
    PythonVariable(const std::map<std::string, PythonVariable>& value) : type(MAP), mapValue(value) {}

    Type getType() const {
        return type;
    }

    int getIntegerValue() const {
        if (type!= INTEGER) {
            throw std::runtime_error("PythonVariable is not an integer");
        }
        return integerValue;
    }

    std::string getStringValue() const {
        if (type!= STRING) {
            throw std::runtime_error("PythonVariable is not a string");
        }
        return stringValue;
    }

    std::vector<PythonVariable> getArrayValue() const {
        if (type!= ARRAY) {
            throw std::runtime_error("PythonVariable is not an array");
        }
        return arrayValue;
    }

    std::map<std::string, PythonVariable> getMapValue() const {
        if (type!= MAP) {
            throw std::runtime_error("PythonVariable is not a map");
        }
        return mapValue;
    }

private:
    Type type;
    int integerValue;
    std::string stringValue;
    std::vector<PythonVariable> arrayValue;
    std::map<std::string, PythonVariable> mapValue;
};

int main() {
    PythonVariable integerVar(42);
    PythonVariable stringVar("Hello, world!");
